using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;

namespace FrostTodo {
 public static partial class SelfTest {
  static void CheckRecurrence(string path,List<string> checks){
   DateTime friday=new DateTime(2026,10,30),saturday=friday.AddDays(1),monday=friday.AddDays(3);
   Func<string,Todo> repeat=rule=>new Todo{Title="重复检查",Repeat=rule,Created="2026-10-29T12:00:00"};
   Todo daily=repeat("daily");Assert(Logic.View(daily,"today",friday)&&daily.Due=="","undated daily task is in today without inventing a deadline",checks);
   daily.Due="2026-10-01";Assert(Logic.View(daily,"today",friday)&&!Logic.View(daily,"overdue",friday),"stale daily date belongs to current cycle instead of remaining overdue",checks);
   Todo future=repeat("daily");future.Due="2026-11-02";Assert(!Logic.View(future,"today",friday)&&Logic.View(future,"today",monday),"future recurring start date does not appear prematurely",checks);
   Todo single=new Todo{Title="普通"};Assert(!Logic.View(single,"today",friday),"undated one-off task is not incorrectly added to today",checks);single.Due="2026-10-29";Assert(Logic.View(single,"overdue",friday)&&!Logic.View(single,"today",friday),"one-off overdue tasks retain their original deadline",checks);
   daily=repeat("daily");daily.Done=true;Assert(!Logic.View(daily,"today",friday),"archived recurring task stays out of pending today",checks);daily.Done=false;
   Todo undo=daily.Copy();Logic.Complete(daily,friday);Assert(daily.RepeatDue=="2026-10-31"&&daily.Due==""&&!Logic.View(daily,"today",friday)&&Logic.View(daily,"today",saturday),"completing undated daily task hides it today and restores it tomorrow",checks);
   Assert(Logic.View(undo,"today",friday),"undo restores the current recurring occurrence",checks);
   Assert(!Recurrence.Refresh(daily,friday)&&!Logic.View(daily,"today",friday),"refresh never reopens a completed current cycle",checks);
   Todo weekdays=repeat("weekdays");Assert(Logic.View(weekdays,"today",friday)&&!Logic.View(weekdays,"today",saturday)&&Logic.View(weekdays,"today",monday),"undated weekdays exclude weekends and include next Monday",checks);
   weekdays.Due="2026-10-23";Recurrence.Refresh(weekdays,saturday);Assert(weekdays.Due=="2026-11-02"&&!Logic.View(weekdays,"today",saturday),"missed weekday cycles advance to Monday instead of appearing on Saturday",checks);
   weekdays=repeat("weekdays");Logic.Complete(weekdays,friday);Assert(weekdays.RepeatDue=="2026-11-02","Friday weekday completion skips the weekend",checks);
   Todo weekly=repeat("weekly");Assert(!Logic.View(weekly,"today",friday)&&Logic.View(weekly,"today",new DateTime(2026,11,5)),"weekly tasks use their scheduled weekday rather than every day",checks);
   weekly.Due="2026-11-12";Assert(!Logic.View(weekly,"today",new DateTime(2026,11,5)),"weekly future start cannot be bypassed by matching weekday",checks);
   Todo month=repeat("monthly");month.Due="2026-01-31";month.Anchor=31;Assert(Logic.View(month,"today",new DateTime(2026,2,28))&&!Logic.View(month,"today",new DateTime(2026,3,1))&&Logic.View(month,"today",new DateTime(2026,3,31)),"monthly schedules clamp February and return to day 31",checks);
   Assert(Logic.View(month,"today",new DateTime(2028,2,29)),"monthly recurrence includes leap-day month end",checks);Recurrence.Refresh(month,new DateTime(2026,2,28));Logic.Complete(month,new DateTime(2026,2,28));Assert(month.Due=="2026-03-31"&&month.Anchor==31,"completing short-month occurrence preserves the original monthly anchor",checks);
   Todo custom=repeat("custom");custom.WeekDays=new List<int>{1,5};Assert(Logic.View(custom,"today",friday)&&!Logic.View(custom,"today",saturday)&&Logic.View(custom,"today",monday),"custom repeat matches only selected weekdays",checks);
   custom.Due="2026-11-04";Assert(!Logic.View(custom,"today",monday)&&Logic.View(custom,"today",new DateTime(2026,11,6)),"custom schedule respects its future start date",checks);
   custom.WeekDays.Clear();Assert(!Logic.View(custom,"today",new DateTime(2026,11,6)),"invalid empty custom rule does not silently become daily",checks);
   daily=repeat("daily");daily.Reminder="2026-10-29T09:00";daily.ReminderFired=true;Assert(Recurrence.Refresh(daily,friday)&&daily.Reminder=="2026-10-30T09:00"&&!daily.ReminderFired&&daily.Due=="","new day advances undated recurring reminder and rearms it",checks);
   Assert(!Recurrence.ReminderDue(daily,friday.AddHours(8))&&Recurrence.ReminderDue(daily,friday.AddHours(9)),"current recurring alarm respects its time after rollover",checks);Recurrence.FireReminder(daily,friday.AddHours(9));Assert(!Recurrence.Refresh(daily,friday)&&!Recurrence.ReminderDue(daily,friday.AddHours(10)),"same-cycle refresh cannot fire a reminder twice",checks);
   Todo longMiss=repeat("daily");longMiss.Due="2026-01-01";longMiss.Reminder="2026-01-01T18:00";longMiss.ReminderFired=true;Recurrence.Refresh(longMiss,friday);Assert(longMiss.Due=="2026-10-30"&&longMiss.Reminder=="2026-10-30T18:00"&&!Recurrence.ReminderDue(longMiss,friday.AddHours(10)),"restart skips missed cycles without replaying old daily alarms",checks);
   weekly=repeat("weekly");weekly.Due="2026-10-22";weekly.Reminder="2026-10-21T18:00";Recurrence.Refresh(weekly,new DateTime(2026,11,5));Assert(weekly.Due=="2026-11-05"&&weekly.Reminder=="2026-11-04T18:00","weekly reminder retains its advance-notice offset",checks);
   Todo reminderStart=repeat("daily");reminderStart.Reminder="2026-11-02T09:00";Recurrence.Reset(reminderStart,friday);Assert(!Logic.View(reminderStart,"today",friday)&&Logic.View(reminderStart,"today",monday)&&reminderStart.Reminder=="2026-11-02T09:00","explicit first reminder can start an otherwise undated series in the future",checks);
   daily=repeat("daily");daily.Reminder="2026-10-30T09:00";Recurrence.Reset(daily,friday);Recurrence.FireReminder(daily,friday.AddHours(9));Recurrence.Snooze(daily,friday.AddHours(9));Assert(daily.Reminder=="2026-10-30T09:00"&&daily.SnoozedUntil=="2026-10-30T09:10"&&!Recurrence.ReminderDue(daily,friday.AddHours(9).AddMinutes(9))&&Recurrence.ReminderDue(daily,friday.AddHours(9).AddMinutes(10)),"snoozing delays just one alarm without rewriting the recurring time",checks);
   Recurrence.FireReminder(daily,friday.AddHours(9).AddMinutes(10));Assert(!Recurrence.ReminderDue(daily,friday.AddHours(10))&&daily.SnoozedUntil=="","snoozed alarm fires once then clears its override",checks);Logic.Complete(daily,friday);Assert(daily.Reminder=="2026-10-31T09:00"&&daily.SnoozedUntil=="","next recurring alarm keeps original time after snoozing and completion",checks);
   Todo midnight=repeat("daily");midnight.Reminder="2026-10-29T23:58";Recurrence.Reset(midnight,friday.AddDays(-1));Recurrence.FireReminder(midnight,friday.AddMinutes(-2));Recurrence.Snooze(midnight,friday.AddMinutes(-2));Recurrence.Refresh(midnight,friday);
   Assert(midnight.SnoozedUntil=="2026-10-30T00:08"&&midnight.Reminder=="2026-10-30T23:58"&&Recurrence.ReminderDue(midnight,friday.AddMinutes(8)),"cross-midnight snooze remains absolute while the recurring schedule advances",checks);Recurrence.FireReminder(midnight,friday.AddMinutes(8));Assert(!midnight.ReminderFired&&Recurrence.ReminderDue(midnight,friday.AddHours(23).AddMinutes(58)),"previous-cycle snooze cannot suppress the new day reminder",checks);
   single.Reminder="2026-10-30T08:00";single.ReminderFired=true;Recurrence.Snooze(single,friday.AddHours(8));Assert(Recurrence.ReminderDue(single,friday.AddHours(8).AddMinutes(10)),"one-off snooze still works after its initial alarm fired",checks);Logic.Complete(single,friday);Assert(!Recurrence.ReminderDue(single,friday.AddDays(1))&&single.SnoozedUntil=="","completed task cancels its pending snooze",checks);
   Todo baseline=repeat("daily");baseline.Due="2026-10-29";baseline.Reminder="2026-10-29T09:00";Recurrence.Refresh(baseline,friday.AddDays(-1));Todo draft=baseline.Copy(),current=baseline.Copy();draft.Title="只改标题";Recurrence.Refresh(current,friday);current.ReminderFired=true;Recurrence.MergeEditor(draft,baseline,current);Assert(draft.Due=="2026-10-30"&&draft.RepeatDue=="2026-10-30"&&draft.Reminder=="2026-10-30T09:00"&&draft.ReminderFired&&draft.Title=="只改标题","editing across rollover preserves refreshed dates and fired reminder state",checks);
   draft=baseline.Copy();draft.Due="2026-11-04";draft.Reminder="2026-11-04T10:00";Recurrence.MergeEditor(draft,baseline,current);Assert(draft.Due=="2026-11-04"&&draft.Reminder=="2026-11-04T10:00","explicit editor schedule changes are not overwritten by background refresh",checks);
   Todo withTime=repeat("daily");withTime.Time="09:00";Assert(Recurrence.ValidTime(withTime),"repeat rule allows a time without requiring an optional deadline",checks);withTime.Repeat="none";Assert(!Recurrence.ValidTime(withTime),"one-off task time still requires a date",checks);withTime.Repeat="daily";withTime.Time="25:00";Assert(!Recurrence.ValidTime(withTime),"invalid recurring time is rejected",checks);
   Todo oldReminder=new Todo{Title="旧提醒",Reminder="2026-10-29T09:00",ReminderFired=true};Todo edited=oldReminder.Copy();Assert(Recurrence.ValidReminder(edited,oldReminder,friday),"editing an existing fired reminder does not require rescheduling it",checks);edited.Reminder="2026-10-28T09:00";Assert(!Recurrence.ValidReminder(edited,oldReminder,friday),"new or changed past reminders remain invalid",checks);
   Todo beforeSort=repeat("daily");beforeSort.Reminder="2026-10-30T09:00";Recurrence.Reset(beforeSort,friday);Todo afterAlarm=beforeSort.Copy();Recurrence.FireReminder(afterAlarm,friday.AddHours(9));Recurrence.MergeDeliveryState(beforeSort,afterAlarm,friday);Assert(beforeSort.ReminderFired&&!Recurrence.ReminderDue(beforeSort,friday.AddHours(9)),"undoing a sort cannot refire an alarm delivered after the snapshot",checks);
   Todo beforeComplete=repeat("daily");Recurrence.Reset(beforeComplete,friday);Todo afterComplete=beforeComplete.Copy();Logic.Complete(afterComplete,friday);Recurrence.MergeDeliveryState(beforeComplete,afterComplete,friday);Assert(Logic.View(beforeComplete,"today",friday)&&!Logic.View(afterComplete,"today",friday),"undoing recurring completion still restores the completed occurrence",checks);
   Todo reset=repeat("weekly");Recurrence.Reset(reset,friday);Assert(Logic.View(reset,"today",friday)&&!Logic.View(reset,"today",new DateTime(2026,11,5)),"changing an undated repeat rule uses the new first date",checks);
   Recurrence.Snooze(midnight,friday.AddHours(23).AddMinutes(58));AppData data=new AppData{Tasks=new List<Todo>{daily,midnight,month}};Store store=new Store(Path.Combine(path,"recurrence"));store.Save(data);AppData loaded=store.Load();Assert(loaded.Tasks[0].RepeatDue==daily.RepeatDue&&loaded.Tasks[1].Reminder==midnight.Reminder&&loaded.Tasks[1].SnoozedUntil=="2026-10-31T00:08"&&loaded.Tasks[1].SnoozedFor==midnight.SnoozedFor&&loaded.Tasks[2].Anchor==31,"recurrence date and alarm state persist across restart",checks);
   Todo copied=midnight.Copy();Assert(copied.RepeatDue==midnight.RepeatDue&&copied.SnoozedUntil==midnight.SnoozedUntil&&copied.SnoozedFor==midnight.SnoozedFor,"undo snapshots retain recurrence and snooze state",checks);
   Todo lateNotice=repeat("daily");lateNotice.Reminder="2026-10-29T23:58";Recurrence.Reset(lateNotice,friday.AddDays(-1));string notifiedCycle=Recurrence.FireReminder(lateNotice,friday.AddMinutes(-2));Recurrence.Refresh(lateNotice,friday);Recurrence.Snooze(lateNotice,friday.AddMinutes(2),notifiedCycle);Assert(lateNotice.SnoozedFor=="2026-10-29"&&lateNotice.SnoozedUntil=="2026-10-30T00:12","snooze clicked on an old notification after midnight retains the notified cycle",checks);string firedCycle=Recurrence.FireReminder(lateNotice,friday.AddMinutes(12));Assert(firedCycle=="2026-10-29"&&!lateNotice.ReminderFired&&Recurrence.ReminderDue(lateNotice,friday.AddHours(23).AddMinutes(58)),"repeated snooze of yesterday notification leaves today's regular alarm armed",checks);
   Todo legacy=store.Decode("{\"Version\":1,\"Tasks\":[{\"Id\":\"legacy\",\"Title\":\"每日\",\"Repeat\":\"daily\",\"Due\":\"\",\"Created\":\"2026-10-01T12:00:00\"}]}").Tasks[0];Assert(Logic.View(legacy,"today",friday)&&Recurrence.Refresh(legacy,friday)&&legacy.RepeatDue=="2026-10-30"&&legacy.Due=="","legacy undated recurring tasks migrate without losing their optional date",checks);
   Todo[] counts={legacy,future,new Todo{Title="今天",Due="2026-10-30"},new Todo{Title="已完成",Due="2026-10-30",Done=true}};Assert(counts.Count(t=>Logic.View(t,"today",friday))==2,"today list and floating counter share the same recurring filter",checks);
  }
 }
